// Uma URL por item; o nó seguinte busca todas. Para adicionar fonte, inclua
// a URL aqui e trate o formato da resposta em "Montar vagas".
const REMOTAR = ['estágio', 'estagio', 'júnior', 'junior', 'trainee'];
const GITHUB = ['frontendbr/vagas', 'backend-br/vagas', 'react-brasil/vagas', 'soujava/vagas-java'];
const HIMALAYAS = [
  'q=desenvolvedor&sort=recent',
  'q=estagio&sort=recent',
  'q=developer&country=Brazil&seniority=Entry-level&sort=recent',
  // Remotas de fora do Brasil abertas a quem mora aqui: country=Brazil traz só
  // vagas cuja lista de países inclui o Brasil (ou sem restrição). Buscas em
  // espanhol para pegar as de empresas hispânicas/LATAM.
  'q=desarrollador&country=Brazil&sort=recent',
  'q=datos&country=Brazil&sort=recent',
  'q=remoto&country=Brazil&seniority=Entry-level&sort=recent',
  'q=latam&country=Brazil&seniority=Entry-level&sort=recent',
];

// GetOnBoard (getonbrd.com): vagas de tecnologia da América Latina, API pública
// sem chave. expand traz o nome da empresa e os países/regiões aceitos no
// remoto. O filtro de modalidade e de país fica em "Montar vagas".
const GETONBRD_EXPAND = encodeURIComponent('["company","location_tenants","location_regions"]');
const GETONBRD = ['junior', 'sin experiencia', 'practicante'];

// Gupy: a página de busca do portal (portal.gupy.io/job-search) já vem com as
// 12 vagas mais recentes no HTML (__NEXT_DATA__); a API antiga saiu do ar.
// Só tipo estágio, mais novas primeiro. Remoto do Brasil todo + o estado de
// "Montar vagas" (ESTADO_LOCAL) para presencial/híbrido.
const GUPY_BASE = 'type=vacancy_type_internship&sortBy=publishedDate&sortOrder=desc';
const GUPY = [
  'term=estágio&workplaceTypes=remote',
  'term=estágio ti&workplaceTypes=remote',
  'term=estágio desenvolvimento&workplaceTypes=remote',
  'term=estágio dados&workplaceTypes=remote',
  'term=estágio&state=Piauí',
  'term=estágio ti',
  'term=estágio desenvolvimento',
  'term=estágio dados',
  'term=estágio software',
  'term=estágio sistemas',
  'term=estágio suporte',
];

// Token do GitHub (GITHUB_TOKEN no GitHub Actions) sobe o limite de 60 para
// 1000 req/h. Sem ele (n8n local) a busca segue sem autenticação.
let githubAuth = '';
try {
  if ($env.GITHUB_TOKEN) githubAuth = `Bearer ${$env.GITHUB_TOKEN}`;
} catch {
  // acesso a $env bloqueado no n8n local: sem token
}

const gupyUrl = (q) =>
  'https://portal.gupy.io/job-search/' + encodeURIComponent(`${q}&${GUPY_BASE}`).replace(/%3D/g, '=').replace(/%26/g, '&');

return [
  ...REMOTAR.map((q) => ({ json: { url: `https://api.remotar.com.br/jobs?search=${encodeURIComponent(q)}` } })),
  ...GITHUB.map((repo) => ({
    json: {
      url: `https://api.github.com/repos/${repo}/issues?state=open&per_page=50&sort=created&direction=desc`,
      auth: githubAuth,
    },
  })),
  ...HIMALAYAS.map((q) => ({ json: { url: `https://himalayas.app/jobs/api/search?${q}` } })),
  ...GUPY.map((q) => ({ json: { url: gupyUrl(q) } })),
  ...GETONBRD.map((q) => ({
    json: {
      url: `https://www.getonbrd.com/api/v0/search/jobs?query=${encodeURIComponent(q)}&per_page=100&expand=${GETONBRD_EXPAND}`,
    },
  })),
];

// Recebe as respostas de todas as fontes e devolve as vagas candidatas no
// formato do webhook do VagaSync: { description, url, source, title, company }.
// title e company vão como a fonte publicou (company vazio se a fonte não
// informa): o VagaSync usa os dois para deduplicar antes da IA.
//
// Perfil buscado: estágio (prioridade), trainee e júnior, área de tecnologia,
// vaga em português ou espanhol que não exige inglês nem anos de experiência.
// Remoto de qualquer lugar; presencial/híbrido só em CIDADES_LOCAIS /
// ESTADO_LOCAL. Vaga de fora do Brasil (Himalayas fora do Brasil, GetOnBoard)
// só remota e aberta a quem mora no Brasil: presencial/híbrido lá fora exige
// visto. Ajuste as constantes abaixo para mudar o perfil.
//
// Daqui as candidatas vão para "Checar já cadastradas" (uma chamada só, que
// devolve quais ainda não existem: mesma URL ou mesmo título + empresa de outra
// fonte) e "Separar novas" aplica o teto de envios da rodada só sobre elas.

const JANELA_HORAS = 168;        // só vagas publicadas nos últimos 7 dias
const JANELA_HORAS_GUPY = 720;   // estágio na Gupy fica aberto semanas: 30 dias, se o prazo não passou
const MAX_CANDIDATAS = 300;      // limite do /api/webhook/n8n/check; o teto de envios fica em "Separar novas"
const MAX_DESCRICAO = 7500;      // o VagaSync recusa acima de 8000 caracteres

// Presencial/híbrido só daqui (a Gupy também é buscada por esse estado em "Fontes")
const ESTADO_LOCAL = 'Piauí';
const CIDADES_LOCAIS = ['Teresina'];
const LOCAL_OK = /teresina|piau[ií]|\bPI\b/i;
const PRESENCIAL = /presencial|h[ií]brid|on-?site|hybrid/i;
const REMOTO = /remot|home ?office|anywhere/i;

// Espanhol: práctica/practicante/pasante/becario = estágio
const NIVEL_OK = /est[aá]gi|trainee|aprendiz|j[uú]nior|\bjr\.?\b|entry[- ]level|sem experi[eê]ncia|primeiro emprego|practicante|pr[aá]cticas?\b|pasant[eí]|becari[oa]|sin experiencia|primer empleo/i;
const ESTAGIO = /est[aá]gi|practicante|pr[aá]cticas?\b|pasant[eí]|becari[oa]/i;
// "Desenvolvimento de Negócios" / "Desarrollo de Negocios" não é TI
const AREA_FORA = /desenvolvimento (de )?(neg[oó]cios|humano|organizacional|pessoas|mercado|produtos? f[ií]sic)|desarrollo (de )?(negocios|humano|organizacional|personas|mercado)|business development/i;
const NIVEL_FORA = /s[eê]nior|\bsr\.?\b|\bssr\b|pleno|\bmid[- ]level|especialista|\blead\b|l[ií]der|staff|principal|coordenad|coordinad|gerente|head\b|arquitet|arquitect|\bjefe\b|supervisor/i;
// A área sai do título (e das categorias, no Remotar): a descrição costuma ter
// "autodesenvolvimento", "sistemas de gestão" etc. em vaga de qualquer área.
// "programa" sozinho pegaria "Programa de Estágio" de qualquer área
const AREA_TI = /desenvolv|desarroll|developer|\bdev\b|programa[çc][aã]o|programaci[oó]n|programador|software|front[- ]?end|back[- ]?end|full[- ]?stack|mobile|\bweb\b|dados|datos|\bdata\b|analytics|\bbi\b|\bqa\b|qualidade de software|testes? de software|automa[çc][aã]o de testes|devops|cloud|infra|sysadmin|suporte t[eé]cnico|soporte t[eé]cnico|help ?desk|\bti\b|tecnologia da informa|inform[aá]tica|sistemas|python|java|react|node|\.net|php|sql|rpa|ciberseguran|ciberseguridad|seguran[cç]a da informa|seguridad de la informa|ci[eê]ncia da computa|machine learning|intelig[eê]ncia artificial|inteligencia artificial|programming|cyber ?security|technical support/i;
// Título de outra área. Só derruba se o título não tiver nada de TI
// ("Analista de Dados de Marketing" continua valendo).
const NAO_TI = /marketing|vendas|ventas|comercial|pr[eé][- ]?vendas|\bsales\b|recursos humanos|\brh\b|reclut|jur[ií]dic|direito|abogad|administrativ|financeir|finanzas|cont[aá]b|contador|log[ií]stic|compras|atendimento ao cliente|atenci[oó]n al cliente|customer (success|support|service)|social media|comunica[çc][aã]o|design gr[aá]fico|dise[nñ]o gr[aá]fico|engenharia (civil|mec[aâ]nica|el[eé]trica|qu[ií]mica|de produ)/i;
// Português, espanhol ("inglés avanzado", "nivel de inglés B2") e inglês
const EXIGE_INGLES = /ingl[eêé]s (fluente|fluido|avan[cç]ado|avanzado|intermedi|conversacional|alto)|buen nivel de ingl[eé]s|nivel (de )?ingl[eé]s:? ?(avanzado|intermedio|alto|b2|c1|c2)|ingl[eêé]s:? ?\(?(b2|c1|c2)\b|\b(b2|c1|c2) (de|en) ingl[eé]s|biling[uü]e|fluent english|advanced english|intermediate english|english (fluency|proficiency|is required)|fluency in english/i;
// "2 anos de experiência", "3+ años", "mínimo de 2 anos", "al menos 2 años" —
// 1 ano ainda passa. Faixa que começa em 0 ou 1 ("entre 0 y 4 años", "1 a 2
// anos") também passa: vale o menor número.
const EXIGE_ANOS = /\b([2-9]|\d{2})\s*\+?\s*a[nñ]os?\s+(de\s+)?(experi|atua|trabaj)|(m[ií]nimo|al menos|pelo menos|m[aá]s de|mais de)\s+(de\s+)?([2-9]|\d{2})\s+a[nñ]os|experi[eêé]ncia\s+(m[ií]nima\s+)?(de\s+)?([2-9]|\d{2})\s*\+?\s*a[nñ]os/gi;
const FAIXA_BAIXA = /\b[01]\s*(a|y|e|-|–|até|hasta)\s*$/i;
const exigeAnos = (texto) => {
  for (const m of String(texto).matchAll(EXIGE_ANOS)) {
    if (!FAIXA_BAIXA.test(String(texto).slice(Math.max(0, m.index - 12), m.index))) return true;
  }
  return false;
};

// Vaga de fora do Brasil: além da lista de países da fonte, o texto pode
// restringir a residentes ("solo residentes en España", "must be based in the
// EU", "residir em Portugal"). Só conta frase sobre quem se candidata, não
// sobre a sede da empresa ("somos una empresa ubicada en España"). A frase que
// também cita Brasil/LATAM não conta.
const RESTRICAO_PAIS = /(resid|viv[ei]r en|morar em|must (be )?(based|located|living|live)|need to be (based|located)|(candidat[oae]s?|personas|profesionales|talento|applicants|candidates)\s+(ubicad|localizad|radicad|based|located)|estar (ubicad|radicad|localizad)|(solo|s[oó]lo|[uú]nicamente|exclusivamente|only)\b[^.\n;]{0,25}(residentes?|residents?|candidat|personas|applicants|candidates)|permiso de trabajo|autoriza[çc][aã]o de (trabalho|resid)|work permit|right to work|eligible to work|authori[sz]ed to work|nacionalidad|ciudadan[ií]a|citizenship)[^.\n;]{0,40}?(espa[nñ]a|espanha|spain|portugal|europa|europe|european union|uni[oó]n europea|uni[aã]o europeia|\bue\b|\beu\b|\beea\b|m[eé]xico|argentina|chile|colombia|per[uú]|uruguay|ecuador|costa rica|estados unidos|united states|reino unido|united kingdom|\buk\b|angola|mo[cç]ambique)/i;
const ABERTO_BRASIL = /brasil|brazil|latam|latinoam[eé]rica|am[eé]rica latina|cualquier (pa[ií]s|lugar|parte)|qualquer (pa[ií]s|lugar)|anywhere|worldwide/i;
const restritoAoPais = (texto) =>
  String(texto)
    .split(/[.\n;]+/)
    .some((frase) => RESTRICAO_PAIS.test(frase) && !ABERTO_BRASIL.test(frase));
// Presencial/híbrido escrito no texto de vaga de fora (a fonte marcou remoto,
// mas o texto pede escritório). "presencialidad" e "no presencial" não contam.
const PRESENCIAL_EXTERIOR = /(modalidad|modalidade|modelo|esquema|formato|jornada|r[eé]gimen|regime)( de trabajo| de trabalho)?:?\s*(100\s*%\s*)?(presencial\b|h[ií]brid)|(?<!no )\b(presencial|h[ií]brid[oa])\s+(en|em|desde)\s|\b(on-?site|hybrid) (in|at)\b/i;
// Cadastro em banco de talentos não é vaga
const NAO_E_VAGA = /cadastre-se|banco de talentos|talent pool|n[aã]o encontrou (a sua|sua) vaga/i;
// GetOnBoard: seniority.data.id (GET /api/v0/seniorities)
const GETONBRD_NIVEL = { 1: 'sin experiencia', 2: 'junior', 3: 'semi senior', 4: 'senior', 5: 'expert' };
const CATEGORIAS_REMOTAR = ['Programação', 'Programação Mobile', 'Data Science / Analytics', 'DevOps', 'QA', 'SysAdmin'];
const TAGS_REMOTAR_FORA = /s[eê]nior|pleno|ingl[eê]s|internacional/i;

// Idioma: compara quantas palavras funcionais de cada língua o texto tem
// (artigos, preposições, conjunções). Cada lista só tem palavras exclusivas da
// língua: "de", "que", "para", "a", "o", "no", "do" valem em mais de uma e
// ficam de fora. Palavra com hífen conta inteira, para a ênclise ("analisá-las")
// não virar "las" do espanhol. Português e espanhol valem (vagas LATAM e da
// Espanha/Portugal); recusa quando o inglês tem mais palavras que os dois.
// Texto curto (< MIN_PALAVRAS_IDIOMA) ou empate passa: descartar em /monitoradas
// custa um clique, perder a vaga não tem volta.
const MIN_PALAVRAS_IDIOMA = 40;
const FUNCIONAIS_PT = new Set(['e', 'em', 'da', 'dos', 'das', 'na', 'nas', 'com', 'um', 'uma', 'ao', 'aos', 'à', 'às', 'os', 'não', 'é', 'são', 'você', 'seu', 'sua', 'seus', 'suas', 'pelo', 'pela', 'pelos', 'pelas', 'ou', 'mais', 'também', 'nossa', 'nosso', 'nossos', 'nossas']);
const FUNCIONAIS_EN = new Set(['the', 'and', 'of', 'to', 'with', 'in', 'for', 'is', 'are', 'you', 'your', 'we', 'our', 'on', 'will', 'be', 'this', 'that', 'an', 'or', 'from', 'at', 'by']);
const FUNCIONAIS_ES = new Set(['el', 'la', 'los', 'las', 'y', 'en', 'con', 'del', 'es', 'un', 'una', 'su', 'sus', 'al', 'lo', 'usted', 'nuestro', 'nuestra', 'también']);
const idiomaAceito = (texto) => {
  const palavras = String(texto).toLowerCase().match(/\p{L}+(?:-\p{L}+)*/gu) || [];
  if (palavras.length < MIN_PALAVRAS_IDIOMA) return true;
  const conta = (lista) => palavras.filter((p) => lista.has(p)).length;
  return Math.max(conta(FUNCIONAIS_PT), conta(FUNCIONAIS_ES)) >= conta(FUNCIONAIS_EN);
};

const agora = Date.now();
const limite = agora - JANELA_HORAS * 3600 * 1000;
const limiteGupy = agora - JANELA_HORAS_GUPY * 3600 * 1000;

const limpar = (html) =>
  String(html ?? '')
    .replace(/<\/(p|li|h\d|div)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();

// "Buscar vagas" devolve o corpo como texto (a Gupy responde HTML). Converte
// cada resposta numa lista de objetos no formato original da fonte.
// busca = posição do item em "Fontes" (o resumo do Actions conta por busca)
const respostas = [];
for (const [busca, item] of $input.all().entries()) {
  const corpo = item.json.data;
  if (typeof corpo !== 'string' || corpo === '') continue; // erro de rede/HTTP: ignora a fonte
  if (corpo.trimStart().startsWith('<')) {
    const m = corpo.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
    const lista = m && JSON.parse(m[1]).props?.pageProps?.initialJobList?.data;
    if (Array.isArray(lista)) respostas.push({ busca, data: { gupy: lista } });
    continue;
  }
  let data;
  try {
    data = JSON.parse(corpo);
  } catch {
    continue;
  }
  // GitHub devolve um array de issues
  if (Array.isArray(data)) respostas.push(...data.map((issue) => ({ busca, data: issue })));
  else respostas.push({ busca, data });
}

const vagas = [];

for (const { busca, data } of respostas) {
  // Gupy: { gupy: [...] } — só estágio (o filtro vai na URL)
  if (Array.isArray(data.gupy)) {
    for (const j of data.gupy) {
      const publicada = Date.parse(j.publishedDate);
      if (!j.name || !j.jobUrl || !(publicada >= limiteGupy)) continue;
      if (j.applicationDeadline && Date.parse(j.applicationDeadline) < agora) continue;

      const remoto = j.workplaceType === 'remote';
      const modalidade = remoto ? 'remoto' : j.workplaceType === 'hybrid' ? 'híbrido' : 'presencial';
      const cidade = [j.city, j.state].filter(Boolean).join(' / ');
      vagas.push({
        publicada,
        title: j.name,
        // o parâmetro jobBoardSource muda conforme a página; a vaga é a mesma
        url: j.jobUrl.replace(/\?.*$/, ''),
        source: 'gupy',
        busca,
        company: j.careerPageName ?? '',
        nivel: `${j.name} estágio`,
        // descrição da Gupy começa pelo texto institucional da empresa: a área
        // sai só do título
        area: j.name,
        remoto,
        local: remoto || j.state === ESTADO_LOCAL || CIDADES_LOCAIS.includes(j.city),
        description:
          [
            `${j.name} — ${j.careerPageName ?? ''}`,
            'Tipo: estágio',
            `Modalidade: ${modalidade}${cidade ? ` (${cidade})` : ''}`,
            j.applicationDeadline && `Inscrições até: ${j.applicationDeadline.slice(0, 10).split('-').reverse().join('/')}`,
          ].filter(Boolean).join('\n') + '\n\n' + limpar(j.description),
      });
    }
    continue;
  }

  // GetOnBoard: { data: [{ id, type: 'job', attributes, links }], meta } — vem
  // antes do Remotar, que também tem meta + data. Vagas da América Latina
  // (quase todas de fora do Brasil): só remotas abertas ao Brasil.
  if (Array.isArray(data.data) && data.data.some((j) => j && j.type === 'job' && j.attributes)) {
    for (const j of data.data) {
      const a = j.attributes ?? {};
      const url = j.links?.public_url;
      const publicada = Number(a.published_at) * 1000;
      if (!a.title || !url || !(publicada >= limite)) continue;

      const nome = (r) => r.attributes?.name ?? String(r.id ?? '');
      const paises = (a.location_tenants?.data ?? []).map(nome);
      const regioes = (a.location_regions?.data ?? []).map(nome);
      const remoto = a.remote_modality === 'fully_remote' || a.remote_modality === 'remote_local';
      // fully_remote sem lista = qualquer país; remote_local só vale com o
      // Brasil (ou a América do Sul/Latina) na lista
      const semLista = !paises.length && !regioes.length;
      const abertoBrasil =
        (a.remote_modality === 'fully_remote' && semLista) ||
        paises.some((p) => /bra[sz]il/i.test(p)) ||
        regioes.some((r) => /south[ _]america|latin|am[eé]rica (do sul|del sur|latina)/i.test(r));
      const nivel = [GETONBRD_NIVEL[String(a.seniority?.data?.id)], String(a.modality?.data?.id) === '4' && 'práctica']
        .filter(Boolean)
        .join(', ');
      const company = a.company?.data?.attributes?.name ?? '';
      const onde = semLista ? 'qualquer país' : [...paises, ...regioes].join(', ');
      const modalidade = remoto ? `remoto (${onde})` : a.remote_modality === 'hybrid' ? 'híbrido' : 'presencial';
      vagas.push({
        publicada,
        title: a.title,
        url,
        source: 'getonbrd',
        busca,
        company,
        nivel: `${a.title} ${nivel}`,
        // categoria da fonte ("Programming", "Data Science / Analytics"...) ajuda
        // quando o título é curto; título de outra área continua caindo
        area: `${a.title} ${a.category_name ?? ''}`,
        remoto,
        local: remoto && abertoBrasil,
        exterior: true,
        description:
          [
            `${a.title} — ${company}`,
            `Nível: ${nivel || 'não informado'}`,
            `Modalidade: ${modalidade}`,
            (a.countries ?? []).length && `Países: ${a.countries.join(', ')}`,
          ].filter(Boolean).join('\n') +
          '\n\n' +
          limpar([a.functions, a.description, a.desirable, a.benefits].filter(Boolean).join('\n\n')),
      });
    }
    continue;
  }

  // Remotar: { meta, data: [...] }
  if (data.meta && Array.isArray(data.data)) {
    for (const j of data.data) {
      const publicada = Date.parse(j.createdAt);
      if (!j.title || !j.id || !(publicada >= limite) || j.expired || j.active === false) continue;

      const tags = (j.jobTags ?? []).map((t) => t.tag?.name ?? '').filter(Boolean);
      const categorias = (j.jobCategories ?? []).map((c) => c.category?.name ?? '');
      if (tags.some((t) => TAGS_REMOTAR_FORA.test(t))) continue;
      if (!categorias.some((c) => CATEGORIAS_REMOTAR.includes(c))) continue;

      const remoto = j.type === 'remote';
      const salario = j.jobSalary
        ? [j.jobSalary.from, j.jobSalary.to].filter(Boolean).join(' a ')
        : '';
      const corpo = limpar([j.subtitle, j.description, j.moreInfos].filter(Boolean).join('\n\n'));

      vagas.push({
        publicada,
        title: j.title,
        url: `https://remotar.com.br/job/${j.id}`,
        source: 'remotar',
        busca,
        company: j.companyDisplayName ?? j.company?.name ?? '',
        nivel: `${j.title} ${tags.join(' ')}`,
        // as categorias já foram filtradas por CATEGORIAS_REMOTAR (todas de TI)
        area: `${j.title} ${categorias.join(' ')}`,
        remoto,
        local: remoto || LOCAL_OK.test(`${j.city ?? ''} ${j.state ?? ''}`),
        description:
          [
            `${j.title} — ${j.companyDisplayName ?? j.company?.name ?? ''}`,
            `Tags: ${tags.map((t) => t.replace(/^[^\p{L}]+/u, '')).join(', ')}`,
            `Área: ${categorias.join(', ')}`,
            !remoto && j.city && `Local: ${j.city}${j.state ? ` / ${j.state}` : ''}`,
            salario && `Salário: R$ ${salario}`,
          ].filter(Boolean).join('\n') + '\n\n' + corpo,
      });
    }
    continue;
  }

  // Himalayas: { jobs: [...] } — todas remotas. Só as abertas ao Brasil: lista
  // de países com o Brasil, ou sem lista (qualquer país). Lista sem o Brasil
  // (só Espanha, só UE...) cai.
  if (Array.isArray(data.jobs)) {
    for (const j of data.jobs) {
      const publicada = Number(j.pubDate) * 1000;
      const url = j.applicationLink || j.guid;
      const paises = j.locationRestrictions ?? [];
      if (!j.title || !url || !(publicada >= limite)) continue;
      if (paises.length && !paises.includes('Brazil')) continue;

      const nivel = (j.seniority ?? []).join(', ');
      const onde = !paises.length
        ? 'qualquer país'
        : paises.length > 6
          ? `${paises.length} países, inclui Brasil`
          : paises.join(', ');
      vagas.push({
        publicada,
        title: j.title,
        url,
        source: 'himalayas',
        busca,
        company: j.companyName ?? '',
        nivel: `${j.title} ${nivel}`,
        // as categorias do Himalayas não servem: "Desenvolvimento de Negócios"
        // vem com "Estágio-em-Desenvolvimento"
        area: j.title,
        remoto: true,
        local: true,
        // vaga só para o Brasil segue as regras de sempre; as outras passam
        // também pelas de vaga de fora (texto restrito a residentes, presencial)
        exterior: !(paises.length === 1 && paises[0] === 'Brazil'),
        description:
          [
            `${j.title} — ${j.companyName ?? ''}`,
            `Nível: ${nivel || 'não informado'}`,
            `Modalidade: remoto (${onde})`,
          ].join('\n') + '\n\n' + limpar(j.description || j.excerpt),
      });
    }
    continue;
  }

  // GitHub (frontendbr/vagas, backend-br/vagas...): uma issue por item. A
  // modalidade vem nas labels ou no título ("[Remoto]", "Presencial - SP").
  if (data.html_url && data.title && !data.pull_request) {
    const publicada = Date.parse(data.created_at);
    if (!(publicada >= limite)) continue;

    const labels = (data.labels ?? []).map((l) => l.name).join(', ');
    const marcas = `${data.title} ${labels}`;
    const remoto = REMOTO.test(marcas);
    vagas.push({
      publicada,
      title: data.title,
      url: data.html_url,
      source: 'github',
      busca,
      // a issue não tem campo de empresa; o VagaSync confere de novo com a
      // empresa que a IA extrair
      company: '',
      nivel: marcas,
      // os repositórios buscados são só de vagas de desenvolvimento
      area: `${data.title} desenvolvimento`,
      remoto,
      // sem modalidade informada, deixa passar: a IA lê o texto
      local: remoto || !PRESENCIAL.test(marcas) || LOCAL_OK.test(marcas),
      description: [data.title, labels && `Tags: ${labels}`].filter(Boolean).join('\n') + '\n\n' + limpar(data.body),
    });
  }
}

// Regras comuns a todas as fontes. O título manda no nível: "Júnior" no
// título com "pleno" só no texto (ex: "você vai trabalhar com devs plenos")
// continua valendo.
const passa = (v) =>
  v.local &&
  NIVEL_OK.test(v.nivel) &&
  !NAO_E_VAGA.test(v.title) &&
  !NIVEL_FORA.test(v.title) &&
  !AREA_FORA.test(v.title) &&
  !(NAO_TI.test(v.title) && !AREA_TI.test(v.title)) &&
  AREA_TI.test(v.area) &&
  idiomaAceito(v.description) &&
  !EXIGE_INGLES.test(v.description) &&
  !exigeAnos(v.description) &&
  // vaga de fora do Brasil: só remota e aberta a quem mora aqui
  !(v.exterior && (!v.remoto || restritoAoPais(v.description) || PRESENCIAL_EXTERIOR.test(`${v.title}\n${v.description}`)));

// Estágio primeiro, depois as mais novas; intercala as fontes para nenhuma
// ocupar a rodada toda.
const porFonte = {};
const vistas = new Set();
// A mesma vaga pode vir de várias buscas: guarda todas para a contagem
const buscasPorUrl = {};
for (const v of vagas) (buscasPorUrl[v.url] ??= new Set()).add(v.busca);
const ordem = (v) => (ESTAGIO.test(v.nivel) ? 1 : 0);
for (const v of vagas.sort((a, b) => ordem(b) - ordem(a) || b.publicada - a.publicada)) {
  if (vistas.has(v.url)) continue;
  vistas.add(v.url);
  // mesmo guard do fluxo antigo: nunca mandar item vazio para o webhook
  if (!v.title || !v.url || v.description.length < 20) continue;
  if (!passa(v)) continue;
  (porFonte[v.source] ??= []).push(v);
}

const filas = Object.values(porFonte);
const results = [];
while (results.length < MAX_CANDIDATAS && filas.some((f) => f.length)) {
  for (const fila of filas) {
    const v = fila.shift();
    if (!v || results.length >= MAX_CANDIDATAS) continue;
    results.push({
      json: {
        description: v.description.slice(0, MAX_DESCRICAO),
        url: v.url,
        source: v.source,
        title: v.title,
        company: v.company,
        buscas: [...buscasPorUrl[v.url]],
      },
    });
  }
}

return results;

// Fica só com as candidatas que "Checar já cadastradas" disse que são novas e
// aplica o teto da rodada sobre elas: vagas antigas que reaparecem no feed não
// ocupam lugar, então a fila nunca trava em duplicadas.
//
// Se a checagem falhar (rede, deploy antigo sem a rota), segue como antes:
// as primeiras MAX_POR_EXECUCAO candidatas, e o webhook deduplica uma a uma.
const MAX_POR_EXECUCAO = 40;

const candidatas = $('Montar vagas').all();
const resposta = $input.first()?.json ?? {};
const indices = Array.isArray(resposta.novas) ? resposta.novas : candidatas.map((_, i) => i);

return [...new Set(indices)]
  .filter((i) => Number.isInteger(i) && candidatas[i])
  .slice(0, MAX_POR_EXECUCAO)
  .map((i) => ({ json: candidatas[i].json }));
